-- Импорт данных в PostgreSQL для проекта science-publications
-- Источник: data.sql (экспорт из SQLite от 2026-05-19)
--
-- Отличия от исходного файла:
--   * пропущены django_migrations, django_content_type, auth_permission
--     (эти таблицы заполняет команда migrate)
--   * у всех INSERT добавлены явные списки колонок,
--     поэтому физический порядок столбцов в таблице роли не играет
--   * 0/1 в булевых полях заменены на false/true
--   * moderated_by_id приведён из 1.0 к 1
--   * в конце синхронизируются последовательности id
--
-- Всё выполняется одной транзакцией: при любой ошибке
-- база откатится в исходное состояние.

SET client_encoding = 'UTF8';

BEGIN;

-- убираем учётку, созданную через createsuperuser,
-- чтобы id из дампа не конфликтовали
TRUNCATE TABLE users_user RESTART IDENTITY CASCADE;


-- ===== Пользователи (3) =====



-- ===== Публикации (7676) =====






















-- ===== Журнал активности (25) =====



-- ===== Синхронизация последовательностей =====
-- без этого следующая запись, добавленная через интерфейс,
-- упадёт с ошибкой дублирующегося id
SELECT setval(pg_get_serial_sequence('users_user','id'),
              COALESCE((SELECT MAX(id) FROM users_user), 1));
SELECT setval(pg_get_serial_sequence('core_publication','id'),
              COALESCE((SELECT MAX(id) FROM core_publication), 1));
SELECT setval(pg_get_serial_sequence('core_activitylog','id'),
              COALESCE((SELECT MAX(id) FROM core_activitylog), 1));

COMMIT;
